                    ('iron-crown', 'Iron Crown', 'iron-crown', 'generation-ix', 16, 1560, TRUE, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/1023.png'),
                    ('terapagos', 'Terapagos', 'terapagos', 'generation-ix', 2, 65, TRUE, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/1024.png'),
                    ('pecharunt', 'Pecharunt', 'pecharunt', 'generation-ix', 3, 3, TRUE, 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/official-artwork/1025.png')
            ) AS pf (slug, name, species_slug, introduced_generation_slug, height, weight, is_default, sprite_url)
    )
INSERT INTO
    dex.pokemon_forms (slug, name, species_id, introduced_generation_id, height, weight, is_default, sprite_url, created_at)
SELECT
    pf.slug,
    pf.name,
    ps.id,
    gen.id,
    pf.height,
    pf.weight,
    pf.is_default,
    pf.sprite_url,
    now ()
FROM
    pf
    LEFT JOIN dex.pokemon_species ps ON ps.slug = pf.species_slug
    LEFT JOIN meta.generations gen ON gen.slug = pf.introduced_generation_slug ON CONFLICT (species_id, slug) DO NOTHING;